  'graf.teclat.ajuda': "Fokua grafoan dagoela, erabili geziak ikuspegia mugitzeko. Botoiek hurbiltzeko, urruntzeko, zentratzeko eta pausatzeko aukera ematen dute. Tab teklak hurrengo kontrolera eramaten du.",
  'section.control.rural.titol': "Landa-modua",
  'section.control.rural.subtitol': "Landa-oharrak eta herrien arteko trukea",
  'section.control.rural.lead': "Gorde oharrak gailu honetan eta trukatu fitxategiak konexioak huts egiten duenean. Zuk aukeratzen duzu noiz aktibatu eta zein fitxategi partekatu.",
  'section.control.rural.perAQueTitol': "Zertarako balio du Landa-moduak?",
  'section.control.rural.punt1': "1. Soroan, mendian edo baserrian landa-oharrak idazteko, estaldurarik edo internetik egon ez arren.",
  'section.control.rural.punt2': "2. Karpeta edo USB memoria batean kopia bat gordetzeko, gailu batetik bestera eramateko.",
  'section.control.rural.punt3': "3. Sarea erortzen denean herrien artean abisuak partekatzeko sinatutako larrialdi-paketeak prestatzeko eta egiaztatzeko.",
