  'section.perfil.privacitat.provaXifrat.limit': "Kontaktuak eta mezuak laginak dira. Probak ez dio ezer bidaltzen inori, ez du txaten zifratzea aktibatzen eta ez du benetako elkarrizketarik berreskuratzen.",
