  /* VQ · Fase 3a (261030) · El panell de la Viquipèdia d'una fitxa incompleta (pobles/CreditsDeViquipedia.jsx). */
  'section.detail.pobles.viquipedia.titol': 'Osatu fitxa hau Viquipèdiarekin',
  'section.detail.pobles.viquipedia.explica': 'Herri honen fitxari datu batzuk falta zaizkio. Zure nabigatzaileak Viquipèdiatik (katalanezko Wikipediatik), Wikidatatik eta Wikimedia Commonsetik ekar ditzake, publikoak eta libreak baitira. Botoia sakatu arte, ez da inorekin konektatzen. Sakatzen duzunean, Wikimediak herriaren izena eta zure IP helbidea jasotzen ditu, cookierik gabe eta orri honen helbiderik gabe. Ekartzen dena nabigatzaile honetan bakarrik gordetzen da, eta ez da ezer idazten Sóc de Pobleren zerbitzarian.',
  'section.detail.pobles.viquipedia.recorda': 'Gogoratu nabigatzaile honetan',
  'section.detail.pobles.viquipedia.porta': 'Ekarri Viquipèdiatik',
  'section.detail.pobles.viquipedia.senseXarxa': 'Konexiorik gabe: orain ezin da ezer ekarri Viquipèdiatik.',
  'section.detail.pobles.viquipedia.noDisponible': 'Orain ezin izan dugu Viquipèdiarekin hitz egin. Ez da ezer gorde.',
  'section.detail.pobles.viquipedia.senseArticle': 'Ez dugu aurkitu izen hau duen eta ziur bat datorren udalerririk, eta ez da ezer gehitu.',
  'section.detail.pobles.viquipedia.creditsTitol': 'Nondik dator fitxa hau',
  'section.detail.pobles.viquipedia.intro': 'Fitxa honi falta zitzaizkion datuak iturri publiko eta libreetatik datoz, eta nabigatzaile honetan bakarrik gordetzen dira.',
  'section.detail.pobles.viquipedia.text': 'Testua:',
