  'section.login.registre.enviatTitol': 'Baieztatu zure kontua',
  'section.login.registre.enviatText': 'Baieztapen-esteka {correu} helbidera bidali dugu. Baieztatu ondoren, itzuli hona eta sartu zure posta elektronikoarekin eta pasahitzarekin.',
