  'section.login.registre.titolEntrar': 'Sartu zure kontuan',
  'section.login.registre.titolCrear': 'Sortu zure kontua',
  'section.login.registre.introEntrar': 'Sartu zure kontuaren posta elektronikoarekin eta pasahitzarekin. Google-rekin sortu bazenuen, ez du pasahitzik: sartu Google-rekin.',
  'section.login.registre.introCrear': 'Lehenik, benetako pertsona bat sartzen da. Zure profila pribatua da, eta geroago sortuko dituzun erakundeetatik bereizita geratzen da.',
  'section.login.registre.opcions': 'Sarbide-aukerak',
  'section.login.registre.ajudaContrasenya': 'Gutxienez {minim} karaktere. Ez berrerabili pasahitz zahar bat.',
