  'section.login.registre.botoCrear': 'Sortu kontua',
  'section.login.registre.oblidada': 'Pasahitza ahaztu duzu?',
  'section.login.recuperacio.enviada': 'Helbide horrekin konturen bat badago, pasahitz berri bat ezartzeko esteka bat jasoko duzu. Begiratu spam karpetan ere.',
  'section.login.recuperacio.titol': 'Berreskuratu pasahitza',
  'section.login.recuperacio.intro': 'Idatzi zure kontuaren helbide elektronikoa eta pasahitz berri bat ezartzeko esteka bat bidaliko dizugu.',
  'section.login.recuperacio.reenvia': 'Bidali esteka berriro',
  'section.login.recuperacio.envia': 'Bidali esteka',
  'section.login.recuperacio.espera': '{segons} s barru eskatu ahal izango duzu berriro.',
  'section.login.recuperacio.tornaAEntrar': 'Itzuli saio-hasierara',
  'section.login.recuperacio.demanaEnllac': 'Eskatu esteka berri bat',
  'section.login.recuperacio.novaTitol': 'Ezarri pasahitz berria',
  'section.login.recuperacio.novaCompte': 'Kontua: {correu}.',
  'section.login.recuperacio.novaIntro': 'Aukeratu hemendik aurrera saioa hasteko erabiliko duzun pasahitza.',
  'section.login.recuperacio.novaCamp': 'Pasahitz berria',
  'section.login.recuperacio.novaConfirma': 'Baieztatu pasahitz berria',
  'section.login.recuperacio.novaDesa': 'Gorde pasahitz berria',
  'section.login.recuperacio.eixir': 'Irten kontutik',
  'section.login.recuperacio.perdutTitol': 'Ireki berriro mezuko esteka',
  'section.login.recuperacio.perdutText': 'Orria berriro kargatu da eta, segurtasunagatik, ez du gordetzen pasahitz berria ezartzeko esteka. Ireki berriro bidali dizugun mezuko esteka. Jada ez baduzu edo baliogabea dela badio, eskatu beste bat.',
  'section.login.benvinguda.titol': 'Ongi etorri Mas Elektronikora',
  'section.login.benvinguda.lead': 'Sartu parte hartzeko. Barruan, zure identitatea konfiguratu eta taldeak edo enpresak kudeatu ahal izango dituzu.',
  'section.login.benvinguda.perfilPrivat': 'Profil pribatua',
  'section.login.benvinguda.rgpdSegur': 'DBEO segurua',
  'section.login.benvinguda.beta': 'Ongi etorri Sóc de Poble-ren Betara',
  'section.login.benvinguda.text': 'Sarbidea {segur} da eta zure datuak legeak babesten ditu (DBEO 05 Legea). Probak egiten ari garenez, eskertuko dizugu edozein arazo aurkitzen baduzu jakinaraztea, batez ere mugikorrean. Berrikuntzen berri emango dizugu!',
  'section.login.benvinguda.segur': 'guztiz segurua',
  'section.login.benvinguda.compteCreat': 'Kontua sortu da. Ongi etorri Masera.',
  'section.login.benvinguda.deNou': 'Ongi etorri berriro Masera!',
  'section.login.benvinguda.contrasenyaDesada': 'Pasahitz berria gorde da. Ongi etorri berriro Masera!',
  'section.login.servidor.caigut': 'Herriko zerbitzariak ez du erantzuten oraintxe. Proba-moduan jarraitzen duzu: aplikazioa arakatu dezakezu, baina oraindik ezin duzu kontua sortu ezta saioa hasi ere.',
  'section.login.servidor.forcaLocal': 'Behartu tokiko sarrera (Mock)',
  'section.login.servidor.suspesa': 'Proba-modura itzuli zara: aplikazioa lagin-datuekin arakatu dezakezu. Kontua sortzeko edo saioa hasteko, konektatu herriko zerbitzariarekin.',
  'section.login.servidor.connecta': 'Konektatu zerbitzariarekin',
  'section.login.servidor.tornaAProves': 'Itzuli proba-modura',
  'section.login.google.titol': 'Sarbide azkarra Google-rekin',
  'section.login.google.entradilla': 'Sortu kontua edo sartu bertan klik bakarrarekin, pasahitzik gabe.',
  'section.login.google.boto': 'Sartu Google-rekin',
  'section.login.google.espera': 'Amaitu saio-hasiera Google-ren leihoan. Itxi baduzu edo ez baduzu aurkitzen, utzi bertan behera hemen.',
  'section.login.google.marcAvis': 'Marko honen barruan ezin da Google-rekin sartu.',
  'section.login.google.marcText': 'Ireki Sóc de Poble fitxa berri batean sartzeko.',
