  'section.notes.visibilitat.motiu.publicada': 'Ohar bat Hormatik kentzeko oraindik ez dago datu-kontraturik zerbitzariarekin: egunera dezakezu, baina ezin duzu berriro pribatu egin.',
  'section.notes.visibilitat.motiu.preparada': 'Idatzi zerbait oharrean Horman argitaratu ahal izateko.',
