  'section.moderacio.bloqueig.descripcio': 'Ez dituzu haren argitalpenak Horman, Merkatuan eta Agendan ikusiko, ezta haren txateko mezuak ere. {nom}-k ez du abisurik jasoko.',
  'section.moderacio.bloqueig.descripcioEntitat': 'Ez dituzu {nom}-ren argitalpenak Horman, Merkatuan eta Agendan ikusiko. {nom}-k ez du abisurik jasoko.',
  'section.moderacio.bloqueig.desfer': 'Nahi duzunean desegin dezakezu zure profilean, Pribatutasuna eta datuak atalean, edo Txataren kontrolean, Pribatutasuna eta segurtasuna atalean.',
  'section.moderacio.bloqueig.confirma': 'Blokeatu',
  'section.moderacio.bloqueig.fet': '{nom} blokeatu duzu.',
  'section.moderacio.bloqueig.nomesSessio': '{nom} saio honetarako blokeatu duzu: zerbitzariak oraindik ez ditu blokeoak gordetzen.',
  'section.moderacio.desbloqueig.fet': '{nom} desblokeatu duzu.',
  'section.moderacio.normes.titol': 'Herriko bizikidetza arauak',
  'section.moderacio.normes.intro': 'Lehen aldiz argitaratu aurretik, irakurri itzazu. Gutxi dira eta zentzuzkoak.',
  'section.moderacio.normes.respecte': 'Errespetatu pertsonak: irainik, mehatxurik, jazarpenik eta diskriminaziorik ez.',
  'section.moderacio.normes.contingut': 'Eduki sexual esplizitu, bortitz edo legez kanpokorik ez, ezta inor arriskuan jartzen duen ezer ere.',
  'section.moderacio.normes.enganys': 'Engainurik ez: ez spamik, ez iruzurrik, ez inoren nortasuna ordezkatzerik, ez desinformazioa zabaltzerik.',
  'section.moderacio.normes.drets': 'Argitaratu zurea dena edo partekatzeko baimena duzuna bakarrik, eta errespetatu besteen intimitatea.',
  'section.moderacio.normes.toleranciaZero': 'Zero tolerantzia arau hauek betetzen ez dituen edukiarekin: beti kentzen dugu. Argitaratzen duenari, larritasunaren arabera eta errepikatzen den ala ez, abisu bat ematen diogu, kontua aldi baterako eteten diogu edo kanporatzen dugu; legez kanpoko eduki larria bada, berehala kanporatzen dugu. Salaketa bakoitza {termini} berrikusten dugu.',
  'section.moderacio.normes.eines': 'Argitalpen eta mezu bakoitzaren ⋮ botoitik eduki bat salatu edo pertsona bat blokeatu dezakezu.',
  'section.moderacio.normes.accepte': 'Bizikidetza arauak irakurri ditut eta onartzen ditut.',
  'section.moderacio.normes.continua': 'Onartu eta jarraitu',
