  'section.plugin.eina.desactiva': 'Desaktibatu tresna hau',
  'section.plugin.eina.reactiva': 'Aktibatu berriro tresna hau',
  'section.plugin.eina.notaActiva': 'Desaktibatzeak zure Kontrol paneletik kentzen du soilik, nabigatzaile honetan. Ez da ezabatzen bertan duzun ezer.',
  'section.plugin.eina.notaDesactivada': 'Zuretzat desaktibatuta dago, nabigatzaile honetan bakarrik. Berriro aktibatzen baduzu, zure Kontrol panelera itzuliko da.',
  'section.plugin.eina.notaApagada': 'Tresnen zerrendan desaktibatu duzu, nabigatzaile honetan bakarrik. Berriro aktibatzen baduzu, hemen ireki ahal izango duzu berriro, web honek duenean.',
  'section.plugin.eina.camiPosar': 'Ez duzu ezer instalatu edo deskargatu behar. Tresna hau web hau kudeatzen duenak bakarrik gehi dezake, prest dagoenean. Orduan, hementxe izango duzu irekitzeko botoia.',
  'section.plugin.eina.camiDemanar': 'Ez duzu ezer instalatu edo ordaindu behar. Web hau kudeatzen duenak bakarrik jar dezake martxan: erabili nahi baduzu, eskatu iezaiozu.',
  'section.plugin.eina.errorDesa': 'Ezin izan da aldaketa gorde. Saiatu berriro.',
