  'plataforma.motiu.documentNoPropi': 'Osasun-datuak gordetzen ditu: Sóc de Pobleren berezko orrian bakarrik irekitzen da, inoiz ez beste web baten barruan.',
  'plataforma.motiu.documentNoPropiFinanceres': 'Finantza-datuak gordetzen ditu: Sóc de Pobleren berezko orrian bakarrik irekitzen da, inoiz ez beste web baten barruan.',
