  /* Pla 261028_1526 (P1-22, TE-01) · La resta de «Privacitat i dades» (DetallPrivacitat.jsx, TEXTOS_PRIVACITAT). Pendent de revisió nadiua. */
  'section.perfil.privacitat.pagina.titol': 'Pribatutasuna eta datuak',
  'section.perfil.privacitat.pagina.lead': 'Gordetzen dugunaren gaineko zure eskubideak: datuen kopia bat, baimena eta baja.',
  'section.perfil.privacitat.pagina.buit': 'Nodo honek ez du oraindik aukera horietako bat ere eskaintzen.',
  'section.perfil.privacitat.dades.titol': 'Nire datuak',
  'section.perfil.privacitat.dades.explica': 'Deskargatu Sóc de Poblek zure kontuaz gordetzen dituen datuen kopia bat: profila, erakundeak, argitalpenak, oharrak, elkarrizketak, zure fitxategien eta eranskinen zerrenda, baimenak, egin dituzun salaketak, blokeatu dituzun edo jarraitzen diezun pertsonak eta erakundeak, eta onartu dituzun arauak. Beste pertsonak babesteko, ez dugu esaten nork salatu zaituen, nork blokeatu zaituen edo nork jarraitzen dizun: zuri buruzko salaketetatik, neurri batekin amaitu direnen kopurua bakarrik dago (xehetasuna nahi baduzu, eskatu iezaguzu posta elektronikoz) eta, jarraitzen dizutenetatik, zenbat pertsona diren. Ez ditugu sartzen IP helbidearen aztarnak, ezta Appleren baimen zifratua ere. JSON fitxategi bat da, edozein testu-editorerekin ireki dezakezuna.',
  'section.perfil.privacitat.dades.fet': 'Fitxategia deskargetan duzu jada. Fitxategiaren izena: {nom}.',
  'section.perfil.privacitat.dades.descarrega': 'Deskargatu nire datuak',
  'section.perfil.privacitat.dades.error': 'Ezin izan dira zure datuak prestatu. Saiatu berriro.',
  'section.perfil.privacitat.politica.llegir': 'Irakurri politika',
  'section.perfil.privacitat.politica.oblitRuralResum': 'Landa Ahazte Osasungarria: Sóc de Poble, El Rentonar eta Coordinadora d’Estudis Eòlics del Comtat erakundeen memoria historikoa, finkatutako argitalpenekin eta laster-markekin batera, beti babestuta geratzen da eta ez da inoiz iraungitzen.',
  'section.perfil.privacitat.consentiment.titol': 'Baimena',
  'section.perfil.privacitat.consentiment.comprovant': 'Baimena egiaztatzen…',
  'section.perfil.privacitat.consentiment.errorLectura': 'Ezin izan da baimenaren egoera irakurri.',
