  'section.perfil.privacitat.consentiment.senseConstancia': 'Ez dago jasota pribatutasun-politika onartu duzunik.',
  'section.perfil.privacitat.consentiment.acceptada': 'Onartu egin duzu ({versio} bertsioa). Data: {data}.',
