  'section.perfil.privacitat.consentiment.vigent': 'Indarreko pribatutasun-politika: {versio} bertsioa.',
  'section.perfil.privacitat.consentiment.senseVigent': 'Oraindik ez dago pribatutasun-politikarik argitaratuta.',
  'section.perfil.privacitat.consentiment.calTitol': 'Zure baimena behar dugu',
  'section.perfil.privacitat.consentiment.accepta': 'Onartu {versio} bertsioa',
  'section.perfil.privacitat.consentiment.calText': 'Indarreko politika onartu gabe, ez zara herriko erroldan agertzen.',
  'section.perfil.privacitat.consentiment.retira': 'Kendu baimena',
  'section.perfil.privacitat.consentiment.retiraDescripcio': 'Herriko erroldan agertzeari utziko diozu, berriro onartu arte.',
  'section.perfil.privacitat.consentiment.retiraConfirma': 'Kendu',
  'section.perfil.privacitat.consentiment.retiraText': 'Kontua ez da ezabatzen: horretarako, eskatu baja. Noiz eman eta kendu duzun jasotzen duen erregistroa gorde egiten da, legeak hori frogatu ahal izatera behartzen gaituelako.',
  'section.perfil.privacitat.baixa.titol': 'Baja eman',
  'section.perfil.privacitat.baixa.comprovant': 'Kontuaren egoera egiaztatzen…',
  'section.perfil.privacitat.baixa.errorLectura': 'Ezin izan da egiaztatu baja bat zain duzun.',
