  'section.perfil.privacitat.baixa.cancelada': 'Baja bertan behera utzi da. Zure profila lehen bezala dago berriro.',
  'section.perfil.privacitat.baixa.errorCancela': 'Ezin izan da baja bertan behera utzi.',
  'section.perfil.privacitat.baixa.pendentTitol': 'Baja bat zain duzu',
  'section.perfil.privacitat.baixa.cancela': 'Utzi baja bertan behera',
  'section.perfil.privacitat.baixa.pendent': 'Baja eskatu duzu. Eskaeraren data: {demanada}. Kontua, zure argitalpen pertsonalak eta zure fitxategiak behin betiko ezabatuko dira data honetan: {purga}. Salbuespena: erakunde batek (bere fitxak edo argitalpen batek) edo beste pertsona baten argitalpen batek oraindik erabiltzen dituen fitxategiak. {apple}',
  'section.perfil.privacitat.baixa.esperaApple': 'Applerekin sartu bazinen eta oraindik ezin izan badugu baimena kendu, ezabaketa gehienez {diesApple} egun gehiagoz atzeratu daiteke.',
  'section.perfil.privacitat.baixa.explica': 'Joaten bazara, berehala ezkutatzen dugu zure profila: erroldan agertzeari uzten dio, zure izenaren ordez izen generiko bat jartzen diogu eta argazkia kentzen diogu. {dies} egun dituzu damutzeko. Epe hori igarotakoan, betiko ezabatzen dira kontua, zure argitalpen pertsonalak eta zure fitxategiak, erakunde batek (bere fitxak edo argitalpen batek) edo beste pertsona baten argitalpen batek oraindik erabiltzen dituenak izan ezik; erakunde baten izenean argitaratu zenuena erakundearen esku geratzen da. {apple}',
  'section.perfil.privacitat.baixa.boto': 'Eman baja',
  'section.perfil.privacitat.baixa.dialegTitol': 'Baja eman',
  'section.perfil.privacitat.baixa.dialegDescripcio': '{dies} egun dituzu atzera egiteko.',
  'section.perfil.privacitat.baixa.confirma': 'Bai, eman baja',
  'section.perfil.privacitat.baixa.punt.amaga': 'Oraintxe bertan ezkutatzen dugu zure profila: erroldan agertzeari uzten dio, zure izenaren ordez izen generiko bat jartzen diogu eta argazkia kentzen diogu, eta zure argitalpenek zure izena eta argazkia erakusteari uzten diote.',
  'section.perfil.privacitat.baixa.punt.cancela': '{dies} egunez bertan behera utz dezakezu: sartu berriro betiko moduan (posta elektronikoarekin, Applerekin edo Googlerekin), itzuli «Pribatutasuna eta datuak» atalera eta sakatu «Utzi baja bertan behera».',
  'section.perfil.privacitat.baixa.punt.apple': 'Applerekin sartu bazinen, baja eskatzean Sóc de Pobleri eman zenion baimena kentzen saiatzen gara; lortzen ez badugu, zuk zeuk ken dezakezu Ezarpenak › zure izena › Hasi saioa Applerekin atalean, edo account.apple.com helbidean. {dies} egunak igarotzean oraindik ezin izan badugu kendu, behin betiko ezabaketa gehienez {diesApple} egun gehiagoz atzeratu daiteke. Kendu badugu eta baja bertan behera uzteko Applerekin berriro sartzen bazara, Applek baimena eskatuko dizu berriro.',
  'section.perfil.privacitat.baixa.punt.esborrat': '{dies} egunak igarotakoan, behin betiko ezabatzen dira kontua, zure argitalpen pertsonalak eta zure fitxategiak, erakunde batek (bere fitxak edo argitalpen batek) edo beste pertsona baten argitalpen batek oraindik erabiltzen dituenak izan ezik. Erakunde baten izenean argitaratu zenuena erakundearen esku geratzen da.',
  'section.perfil.privacitat.baixa.punt.conserva': 'Gorde egiten dira, zure konturik gabe baina guztiz anonimo izan gabe, baimenaren froga, legeak gordetzera behartzen gaituena, eta, moderazioaren historiarako, egin zenituen salaketak eta beste pertsona batzuek zuri edo zure edukiari buruz egin dituztenak, zure kontuak zuen barne-identifikatzailearekin.',
  'section.perfil.privacitat.baixa.punt.sessio': 'Saioa itxi egingo da zure gailu guztietan.',
  'section.perfil.privacitat.baixa.motiu': 'Zergatik zoaz? (aukerakoa)',
  'section.perfil.privacitat.baixa.motiuAjuda': 'Hobetzen laguntzen digu. Gehienez 500 karaktere.',
