  'section.notes.desa.lector.ajuda': "Aplikazioak ez du ezer deskargatzen bere kabuz: iturria konektorearen zain geratzen da, ostalariak edo zerbitzariak zerbitzatu arte.",
  'section.notes.desa.lector.nota': "Irakurgailura zure iturri gisa iristen da, gailu honetan bakarrik.",
