  /* T7b · E2EE verificable per conversa i Persones de confiança, darrere de la bandera E2EE (assalt 261101) */
  'section.xat.xifratge.menu': "Zifratzea eta segurtasun-zenbakia",
  'section.xat.xifratge.avisFil': "Txat honetako mezuak eta fitxategiak zure gailuan zifratzen dira irten aurretik. Sóc de Poble-ren zerbitzarira zifratuta bakarrik iristen dira, eta ez dugu haiek irekitzeko gakorik. Hala ere, ikusten dugu nor norekin eta noiz ari den hizketan. Egiaztatu segurtasun-zenbakia ziur egoteko.",
  'section.xat.xifratge.avisFilPersonal': "Txat honetako mezuak eta fitxategiak zure gailuan zifratzen dira irten aurretik. Sóc de Poble-ren zerbitzarira zifratuta bakarrik iristen dira, eta ez dugu haiek irekitzeko gakorik. Hala ere, ikusten dugu noiz idazten duzun. Zuretzat bakarrik den txat batean ez dago konparatzeko segurtasun-zenbakirik.",
  'section.xat.xifratge.iaia': "IAIArekin txata: ez dago muturretik muturrera zifratuta.",
  'section.xat.xifratge.public': "Txat publikoa: sartzen den edonork irakur dezake, eta ez dago muturretik muturrera zifratuta.",
  'section.xat.xifratge.sensePrimitives': "Helbide honetatik ezin da zifratu. Ireki Sóc de Poble aplikazioan edo socdepoble.org-en txat honetan irakurtzeko eta idazteko.",
  'section.xat.xifratge.canviInesperat': "Txat hau ustekabean aldatu da zerbitzarian. Segurtasunagatik, ezin da bertan idatzi.",
  'section.xat.xifratge.entitatPendent': "Erakundeekin dauden txatak ezin dira oraindik muturretik muturrera zifratu: gailu honetatik, oraingoz, ezin da haietan idatzi.",
  'section.xat.xifratge.clauCanviadaForta': "{nom}(e)k segurtasun-gako berri bat du, eta aurreko gakoak ez du berretsi. Norbaitek gailua eta esaldia galtzen dituenean gertatzen da, edo norbait tartean sartu bada. Hitz egin {nom}(r)ekin zer gertatu den jakiteko.",
  'section.xat.xifratge.numero.titol': "Segurtasun-zenbakia",
  'section.xat.xifratge.numero.explica': "Zenbaki hau berdina bada zure gailuan eta {nom}(r)en gailuan, inork ez ditu zuen gakoak bidean aldatu. Konparatu aurrez aurre edo telefonoz.",
  'section.xat.xifratge.numero.calculant': "Segurtasun-zenbakia kalkulatzen…",
  'section.xat.xifratge.numero.marca': "Markatu egiaztatutzat",
  'section.xat.xifratge.numero.desmarca': "Kendu egiaztatu-marka",
  'section.xat.xifratge.numero.verificat': "Egiaztatua: zenbaki hau {nom}(r)ekin konparatu duzu.",
  'section.xat.xifratge.numero.senseClau': "{nom}(e)k oraindik ez ditu txat pribatu zifratuak aktibatu inongo gailutan: oraindik ez dago konparatzeko zenbakirik.",
  'section.xat.xifratge.numero.senseClausPropies': "Gailu honek oraindik ez ditu zure txat pribatuetako gakoak: oraindik ez dago konparatzeko zenbakirik.",
  'section.xat.xifratge.numero.canviat': "{nom}(r)en gakoa aldatu egin da zenbakia begiratzen zenuen bitartean. Konparatu zenbaki berri hau markatu aurretik.",
  'section.xat.xifratge.numero.error': "Ezin izan da segurtasun-zenbakia kalkulatu. Saiatu berriro.",
  'section.xat.xifratge.numero.errorMarca': "Ezin izan da marka gorde. Saiatu berriro.",
  'section.xat.xifratge.numero.grup': "Talde batean, segurtasun-zenbakia pertsona bakoitzarekin konparatzen da, zuen txat pribatutik.",
  /* M02 · canvi de clau (marató 261101_2143) */
  'section.xat.xifratge.clauCanviadaContinua': "{nom}(r)ekin hitz egin dut: jarraitu",
  'section.xat.xifratge.clauCanviadaSuau': "{nom}(r)en segurtasun-gakoa aldatu egin da, eta aurreko gakoak berretsi du.",
  'section.xat.xifratge.verificatBloquejat': "{nom} egiaztatuta zenuen, eta haren gakoa aldatu egin da. Egiaztatu berriro jarraitzeko.",
  'section.xat.xifratge.clauPropiaAlarma': "Gailu honetakoa ez den gako berri bat erregistratu da zure konturako. Zu izan ez bazara, jakinarazi iezaguzu.",
  'section.xat.xifratge.clauNovaSenseConfirmar': "Gako berria, berretsi gabe",
  'section.xat.xifratge.bifurcacio': "Txat honetako gakoak ez datoz bat gailuen artean. Konparatu segurtasun-zenbakia.",
  'section.xat.xifratge.errorAccepta': "Ezin izan da gako berria berretsi. Saiatu berriro.",
  /* E3 · clau retirada (marató 261101_2143) */
  'section.xat.xifratge.senseClauValida': "Baliozko segurtasun-gakorik gabe",
  'section.xat.xifratge.clauRetirada': "Gailu honek ez du aurkitzen {nom}(r)en baliozko segurtasun-gakorik, berresteko modukorik. Norbaitek gailua eta esaldia galtzen dituenean gertatzen da, edo norbait tartean sartu bada. Baliozko bat egon arte, ezin da idatzi. Hitz egin {nom}(r)ekin zer gertatu den jakiteko.",
  'section.xat.xifratge.clauPropiaRetirada': "Gailu honek ez du zure kontuko gako aktiborik aurkitzen: ez berea, ez beste bat. Baliteke norbait tartean sartu izana. Segurtasunagatik, ezin da idatzi. Zu izan ez bazara, jakinarazi iezaguzu.",
  /* O4-CLAUDE-3 · D-18 (a): avís i confirmació del retall a Notes d’una conversa xifrada */
  'section.xat.xifratge.retall.avis': "Oharra zerbitzarian gordeko da, muturretik muturrerako zifratzerik gabe.",
  'section.xat.xifratge.retall.guarda': "Gorde",
  'section.perfil.privacitat.confianca.titol': "Konfiantzako pertsonak",
  'section.perfil.privacitat.confianca.explica': "Egunen batean gailu guztiak eta esaldia galtzen badituzu, konfiantzako zure pertsonetako hiruk elkarrekin txat pribatuak berreskuratzen lagunduko dizute. Nahi adina izan ditzakezu, gutxienez hiru, eta bakoitzarekin segurtasun-zenbakia egiaztatuta izan behar duzu.",
  'section.perfil.privacitat.confianca.pendent': "Konfiantzako pertsonen bidezko berreskurapena ez dago oraindik aktibatuta nodo honetan: oraingoz, inork ezin dizu lagundu txat pribatuak berreskuratzen.",
  'section.perfil.privacitat.confianca.verificats.cap': "Oraindik ez duzu inongo kontakturen segurtasun-zenbakia egiaztatu.",
  'section.perfil.privacitat.confianca.verificats.un': "Kontaktu 1 duzu segurtasun-zenbakia egiaztatuta.",
  'section.perfil.privacitat.confianca.verificats.diversos': "{n} kontaktu dituzu segurtasun-zenbakia egiaztatuta.",
  'section.perfil.privacitat.confianca.falta.un': "Beste 1 behar da hirura iristeko.",
  'section.perfil.privacitat.confianca.falta.diversos': "Beste {n} behar dira hirura iristeko.",
  'section.perfil.privacitat.confianca.aPunt': "Nahikoa dituzu dagoeneko. Konfiantzako pertsonen bidezko berreskurapena nodo honetan aktibatzen denean, hemen aukeratu ahal izango dituzu.",
  'section.perfil.privacitat.confianca.risc': "Aukeratu benetan fidatzen zaren jendea: horietako hiruk elkarrekin zure segurtasun-kopia ireki lezakete.",
  'section.perfil.privacitat.confianca.error': "Ezin izan da irakurri zein kontaktu dituzun egiaztatuta.",
  'section.perfil.privacitat.confianca.cerimonia.llista': "SAS zeremoniako zirrikituak",
  'section.perfil.privacitat.confianca.cerimonia.ranura': "{n}. zirrikitua · {nom}",
  'section.perfil.privacitat.confianca.cerimonia.ranuraSenseNom': "Konfiantzako lagunaren {n}. zirrikitua",
  'section.perfil.privacitat.confianca.cerimonia.estat.pendent': "SAS egiaztatzeko zain",
  'section.perfil.privacitat.confianca.cerimonia.estat.verificat_sas': "SAS egiaztatuta",
  'section.perfil.privacitat.confianca.cerimonia.estat.disputa': "Eztabaidan («Ez naiz ni»)",
  'section.perfil.privacitat.confianca.cerimonia.detall.pendent': "Alderatu SAS kodea ahotsez edo aurrez aurre laguntza baieztatu aurretik.",
  'section.perfil.privacitat.confianca.cerimonia.detall.verificat_sas': "SAS kodea egiaztatuta eta ekarpena baieztatuta zirrikitu honetarako.",
  'section.perfil.privacitat.confianca.cerimonia.detall.disputa': "Zeremonia geldituta zirrikitu honetako eztabaida-alerta dela eta.",
  'section.perfil.privacitat.confianca.cerimonia.accio.verifica': "Egiaztatu {nom} kontaktuaren SAS kodea",
  'section.perfil.privacitat.confianca.cerimonia.accio.revisa': "Berrikusi {nom} kontaktuaren SAS egiaztapena",
