  'editor.memoriaOral.camp.etiquetes': "Etiketak",
  'editor.memoriaOral.capEtiqueta': "Landa-hiztegiko bat ere ez",
  'editor.memoriaOral.avisos': "Oharrak",
  'editor.memoriaOral.revisada': "Berrikusi dut",
  'editor.memoriaOral.revisadaAjuda': "Deskargatzen duzun fitxa zirriborrotik pertsona batek berrikusira igarotzen da; fitxategiak ez du zure kontuaren identifikatzailerik.",
  'editor.memoriaOral.senseCompte': "Berrikuspena sinatzeko, zure kontuarekin sartu behar duzu.",
  'editor.memoriaOral.errorRevisio': "Ezin izan da berrikuspena sinatu: fitxa zirriborroa da oraindik.",
  'editor.memoriaOral.estat.revisada': "Egoera: pertsona batek berrikusia.",
  'editor.memoriaOral.estat.esborrany': "Egoera: zirriborroa, giza berrikuspenaren zain.",
  'editor.memoriaOral.descarrega': "Deskargatu fitxa",
  'editor.memoriaOral.text': "Fitxa, Markdown formatuan",
  'editor.memoriaOral.senseDescarrega': "Hemen ezin da fitxategi gisa gorde: kopiatu testua.",
  'editor.memoriaOral.motiu.buit': "Oharrak ez du kontakizunik oraindik: idatzi gorputzean eta saiatu berriro.",
  'editor.memoriaOral.motiu.llavor': "Gorputza formatu-txantiloia da oraindik: idatzi bertan kontakizuna eta saiatu berriro.",
  'editor.memoriaOral.motiu.massaLlarg': "Kontakizuna luzeegia da nabigatzailean aztertzeko.",
  /* Gauntlet 261101 · X-OKF */
  'editor.memoriaOral.correccio': "«Berrikusi dut» markatu aurretik, kendu marka egokiak ez diren etiketei eta aukeratu kontakizunaren herria. Zuzenketa fitxan sartzen da berrikusitzat markatzen duzunean; ordura arte, deskargatzen duzuna makinaren proposamena da.",
  'editor.memoriaOral.camp.pobleDelRelat': "Kontakizunaren herria",
  'editor.memoriaOral.capDEstos': "Herri hauetako bat ere ez",
  /* Gauntlet 2 · 261101 · Y-OKF · G2-MO-03 (descripció, resum i el fitxer sencer al diàleg) i G2-MO-07 (avisos i etiquetes pel traductor; en valencià, el text del motor, idèntic). */
  'editor.memoriaOral.camp.descripcio': "Deskribapena",
  'editor.memoriaOral.camp.resum': "Laburpena",
  'editor.memoriaOral.veureFitxa': "Ikusi fitxa osoa",
  'editor.memoriaOral.textSencer': "Fitxategi osoa da, deskargatzen den bezala.",
  'editor.memoriaOral.avis.curt': "Kontakizunak 12 hitz baino gutxiago ditu: fitxa orientagarria da.",
  'editor.memoriaOral.avis.diversosPobles': "Kontakizunak herri bat baino gehiago aipatzen ditu: udalerria berretsi behar da.",
  'editor.memoriaOral.tema.festes': "Jaiak eta ohiturak",
  'editor.memoriaOral.tema.oficis': "Ofizioak eta lanak",
  'editor.memoriaOral.tema.aigua': "Ura",
  'editor.memoriaOral.tema.collita': "Uzta eta landa",
  'editor.memoriaOral.tema.malnoms': "Ezizenak eta goitizenak",
  'editor.memoriaOral.tema.cancons': "Abestiak eta musika",
  'editor.memoriaOral.tema.cuina': "Sukaldaritza eta jakitegia",
  'editor.memoriaOral.tema.bestiar': "Animaliak eta abereak",
  'editor.memoriaOral.tema.infancia': "Haurtzaroa eta eskola",
  'editor.memoriaOral.tema.guerra': "Gerra eta gerraostea",
  'editor.memoriaOral.tema.emigracio': "Emigrazioa eta itzulera",
  'editor.memoriaOral.tema.remeis': "Erremedioak eta jakintzak",
  'editor.memoriaOral.tema.rondalles': "Ipuinak eta esaerak",
  /* T6a · D-5 àlies de poble i etiquetes lliures a la fitxa (assalt 261101) */
  'editor.memoriaOral.correccioAmbAfegir': "«Berrikusi dut» markatu aurretik, kendu marka egokiak ez diren etiketei, gehitu falta direnak eta aukeratu kontakizunaren herria. Zuzenketa fitxan sartzen da berrikusitzat markatzen duzunean; ordura arte, deskargatzen duzuna makinaren proposamena da.",
  'editor.memoriaOral.altrePoble': "Beste herri bat",
  'editor.memoriaOral.altrePobleAjuda': "Idatzi zuk esaten duzun bezala: Xixona edo Jijona, la Torre edo Torremanzanas, Alcoi edo Alcoy.",
  'editor.memoriaOral.triaPoble': "Aukeratu herri hau",
  'editor.memoriaOral.pobleTriat': "Aukeratutako herria: {nom}.",
  'editor.memoriaOral.pobleDesconegut': "Ez dugu izen hori duen herririk ezagutzen. Saiatu izen ofizialarekin edo jendeak erabiltzen duenarekin.",
  'editor.memoriaOral.pobleAmbigu': "Herri batek baino gehiagok dute izen hori: idatzi osorik.",
  'editor.memoriaOral.novaEtiqueta': "Etiketa berria",
  'editor.memoriaOral.novaEtiquetaAjuda': "Hitz bat edo bi, gehienez 40 karaktere. Landa-hiztegikoa bada, ezagutu egiten da.",
  'editor.memoriaOral.etiquetaAfegida': "Etiketa gehituta: {nom}.",
  'editor.memoriaOral.etiquetaInvalida': "Idatzi 2 eta 40 karaktere arteko etiketa bat, letrekin edo zenbakiekin.",
  'editor.memoriaOral.etiquetaRepetida': "Etiketa hori badago jada.",
  'editor.memoriaOral.massaEtiquetes': "Dagoeneko {n} etiketa daude: kendu batzuk gehiago gehitu aurretik.",
  'editor.memoriaOral.massaEtiquetesLliures': "Dagoeneko {n} etiketa libre daude: kendu batzuk gehiago gehitu aurretik.",
  'editor.memoriaOral.afegida': "berrikusketan gehitua",
  'editor.memoriaOral.capPobleAlRelat': "Makinak ez du herririk antzeman kontakizunean",
